#!/usr/bin/env dotnet
#:sdk Microsoft.NET.Sdk.Web #:package OpenTelemetry.Extensions.Hosting@1.7.0 #:package OpenTelemetry.Instrumentation.AspNetCore@1.7.0 #:package OpenTelemetry.Exporter.OpenTelemetryProtocol@1.7.0 #:property LangVersion=preview #:property TargetFramework=net11.0  using OpenTelemetry.Trace;  public static class TracingExtensions {     public static readonly ActivitySource ActivitySource =          new("MQTT.Redis.Integration");              public static IServiceCollection AddOpenTelemetryTracing(this IServiceCollection services)     {         services.AddOpenTelemetry()             .WithTracing(builder => builder                 .AddAspNetCoreInstrumentation()                 .AddRedisInstrumentation()                 .AddOtlpExporter());                          return services;     } }
